def solve(matrix):
    # Determinant using Bareiss algorithm (exact integer arithmetic)
    # Empty matrix has determinant 1 by specification
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square
    if any(len(row) != n for row in matrix):
        raise ValueError("Matrix must be square")
    # Make a deep copy of matrix entries as integers
    a = [list(map(int, row)) for row in matrix]
    sign = 1
    for k in range(n-1):
        # Pivot if zero
        if a[k][k] == 0:
            swap = None
            for i in range(k+1, n):
                if a[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            a[k], a[swap] = a[swap], a[k]
            sign = -sign
        pivot = a[k][k]
        prev_pivot = a[k-1][k-1] if k > 0 else 1
        for i in range(k+1, n):
            for j in range(k+1, n):
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev_pivot
            a[i][k] = 0
    return sign * a[n-1][n-1]

