def solve(n, b):
    """Convert integer n to a string representation in base b (2<=b<=36).
    Negative numbers get a leading '-'. Zero returns '0'.
    Digits 0-9 then a-z for values 10-35.
    """
    if b < 2 or b > 36:
        raise ValueError('Base out of range')
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n > 0:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

