def solve(s):
    """Return the length of the longest substring without repeating characters.
    Handles inputs that are not strings by converting them to a list of elements;
    non‑iterable inputs result in length 0.
    """
    # Normalize input to a sequence of hashable elements
    if isinstance(s, str):
        seq = s
    else:
        try:
            seq = list(s)
        except Exception:
            return 0
    char_index = {}
    left = 0
    max_len = 0
    for right, ch in enumerate(seq):
        # If character seen in current window, move left bound
        prev = char_index.get(ch, -1)
        if prev >= left:
            left = prev + 1
        char_index[ch] = right
        cur_len = right - left + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

def solve(n):
    """Return the number of prime numbers strictly less than n.
    Uses Sieve of Eratosthenes for efficiency.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            step = p
            start = p * p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start)//step + 1)
    return sum(sieve)

