    rows = len(grid)
    visited = [ [False]*len(grid[r]) for r in range(rows) ]
    def bfs(r,c):
        stack = [(r,c)]
        visited[r][c] = True
        while stack:
            i,j = stack.pop()
            # explore four directions
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < len(grid[ni]) and not visited[ni][nj] and grid[ni][nj]==1:
