def solve(s):
    """Return length of longest substring without repeating elements.
    Works for strings, sequences, and handles unhashable elements.
    """
    # Normalize to a sequence
    if isinstance(s, str):
        seq = s
    else:
        try:
            seq = list(s)
        except Exception:
            return 0
    left = 0
    max_len = 0
    last = {}
    for right, ch in enumerate(seq):
        # Determine previous index of ch
        try:
            prev = last.get(ch, -1)
        except TypeError:
            # unhashable element, linear search backward
            prev = -1
            for idx in range(right - 1, left - 1, -1):
                if seq[idx] == ch:
                    prev = idx
                    break
        if prev >= left:
            left = prev + 1
        # update last occurrence if hashable
        try:
            last[ch] = right
        except TypeError:
            pass
        cur_len = right - left + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

def solve(n, b):
    """Convert integer n to its representation in base b (2 <= b <= 36).
    Uses digits 0-9 then a-z for values 10-35. Negative numbers get a leading '-'.
    """
    if b < 2 or b > 36:
        raise ValueError('Base out of range')
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    res = []
    while n > 0:
        n, rem = divmod(n, b)
        res.append(digits[rem])
    if neg:
        res.append('-')
    return ''.join(reversed(res))

